/// One exact endpoint/client observation accumulated across collections.
class AppPeoplePeer {
  final AppPeer peer;
  final Uint32List collections;

  /// True only when this exact endpoint/client is in the current live peer
  /// snapshot. Historical non-zero rates must never imply liveness.
  final bool live;
  final int peakDownBytesPerSecond;
  final int peakUpBytesPerSecond;
  final BigInt lastSeenAt;

  const AppPeoplePeer({
    required this.peer,
    required this.collections,
    required this.live,
    required this.peakDownBytesPerSecond,
    required this.peakUpBytesPerSecond,
    required this.lastSeenAt,
  });

  @override
  int get hashCode =>
      peer.hashCode ^
      collections.hashCode ^
      live.hashCode ^
      peakDownBytesPerSecond.hashCode ^
      peakUpBytesPerSecond.hashCode ^
      lastSeenAt.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AppPeoplePeer &&
          runtimeType == other.runtimeType &&
          peer == other.peer &&
          collections == other.collections &&
          live == other.live &&
          peakDownBytesPerSecond == other.peakDownBytesPerSecond &&
          peakUpBytesPerSecond == other.peakUpBytesPerSecond &&
          lastSeenAt == other.lastSeenAt;
}

/// The complete, app-renderable Nexus projection.
class AppSnapshot {
  final AppDevice device;
  final String connectivity;
  final List<AppContact> contacts;
  final List<AppCollection> collections;
  final List<String> alerts;

  /// What the engine is doing right now, aggregated once here rather than
  /// left for every screen to recompute from `collections` — two Flutter
  /// call sites disagreeing about how many transfers were active ("1 ACTIVE
  /// TRANSFER" above a window reading "0 collections") is exactly the
  /// class of bug one shared derivation exists to make impossible.
  final AppActivity activity;

  const AppSnapshot({
    required this.device,
    required this.connectivity,
    required this.contacts,
    required this.collections,
    required this.alerts,
    required this.activity,
  });

  @override
  int get hashCode =>
      device.hashCode ^
      connectivity.hashCode ^
      contacts.hashCode ^
      collections.hashCode ^
      alerts.hashCode ^
      activity.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AppSnapshot &&
          runtimeType == other.runtimeType &&
          device == other.device &&
          connectivity == other.connectivity &&
          contacts == other.contacts &&
          collections == other.collections &&
          alerts == other.alerts &&
          activity == other.activity;
}

